import { useCallback, useMemo, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

export interface ReportDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
}

type PresetId = 'today' | 'yesterday' | 'weekAgo';

const PRESETS: Array<{ id: PresetId; label: string; offsetDays: number }> = [
  { id: 'today', label: 'Сегодня', offsetDays: 0 },
  { id: 'yesterday', label: 'Вчера', offsetDays: 1 },
  { id: 'weekAgo', label: 'Неделя назад', offsetDays: 7 },
];

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function shiftDays(offsetDays: number): Date {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() - offsetDays);
  return base;
}

function isSameDay(a: Date | null, b: Date | null): boolean {
  if (!a || !b) return false;
  return startOfDay(a).getTime() === startOfDay(b).getTime();
}

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [innerValue, setInnerValue] = useState<Date | null>(defaultValue);
  const isControlled = value !== undefined;
  const currentValue = isControlled ? value : innerValue;

  const applyValue = useCallback(
    (next: Date | null) => {
      if (!isControlled) setInnerValue(next);
      onChange?.(next);
    },
    [isControlled, onChange],
  );

  const activePreset = useMemo(() => {
    const match = PRESETS.find((preset) => isSameDay(currentValue, shiftDays(preset.offsetDays)));
    return match?.id ?? null;
  }, [currentValue]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {PRESETS.map((preset) => (
          <JxChip
            key={preset.id}
            active={activePreset === preset.id}
            role="button"
            tabIndex={0}
            aria-pressed={activePreset === preset.id}
            onClick={() => applyValue(shiftDays(preset.offsetDays))}
            onKeyDown={(event) => {
              if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                applyValue(shiftDays(preset.offsetDays));
              }
            }}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>

      <JxCalendar
        locale={locale}
        value={currentValue}
        onValueChange={applyValue}
        aria-label="Дата отчёта"
      />

      <p style={{ margin: 0, color: 'var(--jx-text-2)', font: 'var(--jx-font-ui, inherit)' }}>
        {currentValue
          ? `Выбрана дата: ${currentValue.toLocaleDateString(locale)}`
          : 'Дата не выбрана'}
      </p>
    </div>
  );
}

